<?php
require_once __DIR__.'/config/module_helpers.php';simrs_require_role(['simrs_admin']);simrs_check_post();$msg=simrs_take_flash();$err='';$generated='';
try{if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='create'){$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$roleId=(int)($_POST['role_id']??0);$unitId=(int)($_POST['unit_id']??0);if($name===''||$username===''||!$roleId)throw new RuntimeException('Nama, username, dan role wajib diisi.');if(!preg_match('/^[A-Za-z0-9._-]{3,60}$/',$username))throw new RuntimeException('Username 3–60 karakter; gunakan huruf, angka, titik, garis bawah, atau minus.');$code='PM'.strtoupper(bin2hex(random_bytes(4))).'!';$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO users (unit_id,full_name,username,password_hash,status) VALUES (?,?,?,?,'active')");$q->execute([$unitId?:null,$name,$username,password_hash($code,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO user_roles (user_id,role_id) VALUES (?,?)');$q->execute([$uid,$roleId]);$pdo->commit();$_SESSION['new_user_code']=['username'=>$username,'code'=>$code];simrs_flash('Akun pengguna berhasil dibuat. Simpan unique code yang ditampilkan; kode tidak disimpan sebagai teks biasa.');simrs_redirect('users.php?created=1');}
 $users=$pdo->query('SELECT u.id,u.full_name,u.username,u.status,u.created_at,r.role_name,r.role_code FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id ORDER BY u.id')->fetchAll();$roles=$pdo->query('SELECT id,role_code,role_name FROM roles WHERE is_active=1 ORDER BY role_name')->fetchAll();$units=$pdo->query('SELECT id,unit_name FROM units WHERE is_active=1 ORDER BY unit_name')->fetchAll();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e instanceof RuntimeException?$e->getMessage():simrs_db_error($e);$users=$users??[];$roles=$roles??[];$units=$units??[];}
$newCode=$_SESSION['new_user_code']??null;if(isset($_GET['created']))unset($_SESSION['new_user_code']);simrs_layout_start('User Management','Dashboard');if($msg)echo '<div class="notice">'.simrs_h($msg).'</div>';if($err)echo '<div class="errorbox">'.simrs_h($err).'</div>';if(isset($_GET['created'])&&$newCode)echo '<div class="notice"><strong>Unique code untuk diberikan kepada pengguna (tampilkan sekali):</strong><br>Username: <strong>'.simrs_h($newCode['username']).'</strong><br>Unique code/password: <strong>'.simrs_h($newCode['code']).'</strong><br>Salin dan simpan sekarang. Hash tersimpan di database; kode asli tidak disimpan.</div>';
?>
<h1>User Management</h1><div class="subtitle">Daftar akun dan role. Hanya administrator SIMRS yang dapat membuat akun baru.</div><div class="formbox"><h2>Buat Pengguna</h2><form method="post"><input type="hidden" name="csrf" value="<?=simrs_h(simrs_token())?>"><input type="hidden" name="action" value="create"><div class="formrow"><div><label>Nama lengkap *</label><input name="full_name" required></div><div><label>Username *</label><input name="username" required pattern="[A-Za-z0-9._-]{3,60}"></div><div><label>Role *</label><select name="role_id" required><option value="">Pilih role</option><?php foreach($roles as $r):?><option value="<?=$r['id']?>"><?=simrs_h($r['role_name'].' ('.$r['role_code'].')')?></option><?php endforeach;?></select></div><div><label>Unit</label><select name="unit_id"><option value="">Tidak ditentukan</option><?php foreach($units as $u):?><option value="<?=$u['id']?>"><?=simrs_h($u['unit_name'])?></option><?php endforeach;?></select></div></div><p class="muted">Sistem membuat unique code otomatis sebagai password awal. Kode hanya ditampilkan setelah akun berhasil dibuat.</p><div class="form-actions"><button class="btn">Buat Akun</button></div></form></div><div class="panel"><div class="panel-title">Daftar Pengguna (<?=count($users)?>)</div><div class="tablewrap"><table><thead><tr><th>ID</th><th>Nama</th><th>Username</th><th>Role</th><th>Role Code</th><th>Status</th><th>Dibuat</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=$u['id']?></td><td><?=simrs_h($u['full_name'])?></td><td><?=simrs_h($u['username'])?></td><td><?=simrs_h($u['role_name']??'Belum ditetapkan')?></td><td><?=simrs_h($u['role_code']??'-')?></td><td><?=simrs_h($u['status'])?></td><td><?=simrs_h($u['created_at'])?></td></tr><?php endforeach;?><?php if(!$users):?><tr><td colspan="7">Belum ada pengguna.</td></tr><?php endif;?></tbody></table></div></div><?php simrs_layout_end(); ?>
